//! OpenAPI 3.1 spec publication (v3.1.2).
//!
//! Three endpoints serve the spec so external clients (curl, Postman,
//! Swagger UI, code generators) can discover and exercise every route
//! without reading source:
//!
//! - `GET /openapi.json` -- JSON spec (machine-readable; embedded at
//!   compile time, so no runtime YAML parser is needed).
//! - `GET /openapi.yaml` -- YAML spec (human-friendly; same source).
//! - `GET /openapi`      -- tiny HTML landing page with links and a
//!   Swagger-UI button (loaded from cdn.jsdelivr.net).
//!
//! The spec is generated by `/home/z/my-project/scripts/gen_openapi.py`
//! and committed at `docs/openapi.{yaml,json}`. Re-run that script
//! whenever the API surface changes.

use axum::http::{header, HeaderValue, StatusCode};
use axum::response::{IntoResponse, Response};
use axum::Json;

/// The OpenAPI 3.1 spec, embedded at compile time as JSON.
const OPENAPI_JSON: &str = include_str!("../../../../docs/openapi.json");

/// The OpenAPI 3.1 spec, embedded at compile time as YAML.
const OPENAPI_YAML: &str = include_str!("../../../../docs/openapi.yaml");

pub fn router() -> axum::Router<crate::state::SharedState> {
    axum::Router::new()
        .route("/openapi.json", axum::routing::get(openapi_json))
        .route("/openapi.yaml", axum::routing::get(openapi_yaml))
        .route("/openapi", axum::routing::get(openapi_landing))
}

/// JSON spec. Parsed at startup so a malformed artifact fails fast
/// instead of returning invalid JSON to clients.
async fn openapi_json() -> Result<Json<serde_json::Value>, (StatusCode, String)> {
    let v: serde_json::Value = serde_json::from_str(OPENAPI_JSON).map_err(|e| {
        (
            StatusCode::INTERNAL_SERVER_ERROR,
            format!("embedded openapi.json is invalid: {e}"),
        )
    })?;
    Ok(Json(v))
}

/// YAML spec served verbatim as `application/yaml`.
async fn openapi_yaml() -> Response {
    (
        StatusCode::OK,
        [
            (header::CONTENT_TYPE, HeaderValue::from_static("application/yaml; charset=utf-8")),
            (header::CACHE_CONTROL, HeaderValue::from_static("public, max-age=300")),
        ],
        OPENAPI_YAML,
    )
        .into_response()
}

/// Tiny HTML landing page. Links to the JSON + YAML endpoints and
/// loads Swagger UI from the jsdelivr CDN so users can browse the spec
/// interactively without installing anything.
async fn openapi_landing() -> Response {
    // `r##"..."##` because the body contains `"#swagger-ui` (which would
    // close `r#"..."#`).
    let html = r##"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>SecuScan v2 API</title>
  <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/swagger-ui-dist@5/swagger-ui.css">
  <style>body { margin: 0; }</style>
</head>
<body>
  <div id="swagger-ui"></div>
  <script src="https://cdn.jsdelivr.net/npm/swagger-ui-dist@5/swagger-ui-bundle.js"></script>
  <script>
    window.onload = () => {
      window.ui = SwaggerUIBundle({
        url: "/api/v1/openapi.json",
        dom_id: "#swagger-ui",
        deepLinking: true,
        presets: [SwaggerUIBundle.presets.apis],
        layout: "BaseLayout",
      });
    };
  </script>
  <noscript>
    This page needs JavaScript. Direct links:
    <a href="/api/v1/openapi.json">openapi.json</a>,
    <a href="/api/v1/openapi.yaml">openapi.yaml</a>.
  </noscript>
</body>
</html>"##;
    (
        StatusCode::OK,
        [(header::CONTENT_TYPE, HeaderValue::from_static("text/html; charset=utf-8"))],
        html,
    )
        .into_response()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_json_parses_and_has_expected_top_level_keys() {
        let v: serde_json::Value =
            serde_json::from_str(OPENAPI_JSON).expect("embedded openapi.json must parse");
        let obj = v.as_object().expect("spec must be a JSON object");
        for key in ["openapi", "info", "servers", "tags", "paths", "components"] {
            assert!(obj.contains_key(key), "spec missing top-level key `{key}`");
        }
        assert_eq!(obj["openapi"], "3.1.0");
        let n_paths = obj["paths"].as_object().map(|m| m.len()).unwrap_or(0);
        assert!(n_paths >= 80, "expected >=80 paths, got {n_paths}");
        let n_schemas = obj["components"]["schemas"]
            .as_object()
            .map(|m| m.len())
            .unwrap_or(0);
        assert!(n_schemas >= 20, "expected >=20 schemas, got {n_schemas}");
    }

    #[test]
    fn embedded_yaml_starts_with_openapi_directive() {
        assert!(
            OPENAPI_YAML.starts_with("openapi: 3.1"),
            "YAML spec must start with `openapi: 3.1`"
        );
    }
}
